<?php
require __DIR__ . '/../app/bootstrap.php';
require_login();
require_once __DIR__ . '/../app/recurring_charges.php';
$user=current_user();
if($_SERVER['REQUEST_METHOD']!=='POST')sync_recurring_charges($pdo);
$error='';$ok='';
$types=['Alquiler','Basura','Luz','Agua','Internet','Electricidad','Reparacion','Otros'];
$periods=['MENSUAL'=>'Mensual','TRIMESTRAL'=>'Trimestral','ANUAL'=>'Anual'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='save'){
   $id=(int)($_POST['id']??0);$scope=$_POST['scope']??'unidad';$unitId=(int)($_POST['unidad_id']??0);$tenantId=(int)($_POST['inquilino_id']??0);
   $type=$_POST['tipo']??'Otros';$concept=trim($_POST['concepto']??'');$amount=max(0,(float)($_POST['importe']??0));$period=$_POST['periodicidad']??'MENSUAL';$start=($_POST['fecha_inicio']??'')?:null;$end=($_POST['fecha_fin']??'')?:null;$priceEffect=trim($_POST['fecha_efecto_precio']??'');$payer=$_POST['pagado_por']??'Inquilino';
   if(!in_array($scope,['unidad','inquilino'],true))throw new RuntimeException('Selecciona el ámbito de la plantilla.');
   if(!in_array($type,$types,true)||!in_array($period,array_keys($periods),true)||!in_array($payer,['Propietario','Inquilino','Otro'],true))throw new RuntimeException('Revisa el tipo, periodicidad y quién paga.');
   if($concept===''||$amount<=0||!$start)throw new RuntimeException('Indica concepto, importe mayor que cero y fecha de inicio.');if($priceEffect!==''&&!preg_match('/^\\d{4}-(0[1-9]|1[0-2])$/',$priceEffect))throw new RuntimeException('El mes de efecto del precio debe tener formato AAAA-MM.');if($id&&$priceEffect==='')throw new RuntimeException('Al editar una plantilla, indica el mes desde el que se aplica el precio.');
   if($end&&$end<$start)throw new RuntimeException('La fecha final no puede ser anterior a la inicial.');
   $unitId=$scope==='unidad'?$unitId:0;$tenantId=$scope==='inquilino'?$tenantId:0;
   if($scope==='unidad'){$q=$pdo->prepare('SELECT COUNT(*) FROM unidades WHERE id=?');$q->execute([$unitId]);if(!$q->fetchColumn())throw new RuntimeException('Selecciona una unidad válida.');}
   else{$q=$pdo->prepare('SELECT COUNT(*) FROM inquilinos WHERE id=?');$q->execute([$tenantId]);if(!$q->fetchColumn())throw new RuntimeException('Selecciona un inquilino válido.');}
   $q=$pdo->prepare("SELECT id FROM cargos_recurrentes WHERE activo=1 AND tipo=? AND LOWER(TRIM(concepto))=LOWER(TRIM(?)) AND ".($scope==='unidad'?'unidad_id=?':'inquilino_id=?')." AND id<>? LIMIT 1");$q->execute([$type,$concept,$scope==='unidad'?$unitId:$tenantId,$id]);if($q->fetchColumn())throw new RuntimeException('Ya existe una plantilla activa con ese tipo y concepto en el mismo ámbito.');
   if($id){
    $q=$pdo->prepare('SELECT * FROM cargos_recurrentes WHERE id=?');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('La plantilla ya no existe.');
    $effectDate=$priceEffect.'-01';$oldAmount=(float)$old['importe'];$priceChanged=abs($oldAmount-$amount)>0.004;
    $pdo->beginTransaction();
    $historyQ=$pdo->prepare('SELECT COUNT(*) FROM cargos_recurrentes_precios WHERE recurrente_id=?');$historyQ->execute([$id]);
    if((int)$historyQ->fetchColumn()===0){$pdo->prepare('INSERT INTO cargos_recurrentes_precios(recurrente_id,fecha_efecto,importe) VALUES(?,?,?)')->execute([$id,substr($old['fecha_inicio'],0,7).'-01',$oldAmount]);}
    if($priceChanged){$latestPriceQ=$pdo->prepare('SELECT MAX(fecha_efecto) FROM cargos_recurrentes_precios WHERE recurrente_id=?');$latestPriceQ->execute([$id]);$latestPrice=$latestPriceQ->fetchColumn();if($latestPrice&&$effectDate<$latestPrice)throw new RuntimeException('El mes de efecto no puede ser anterior al último cambio de precio registrado ('.$latestPrice.').');$pdo->prepare('INSERT INTO cargos_recurrentes_precios(recurrente_id,fecha_efecto,importe) VALUES(?,?,?) ON DUPLICATE KEY UPDATE importe=VALUES(importe)')->execute([$id,$effectDate,$amount]);}
    $pdo->prepare('UPDATE cargos_recurrentes SET unidad_id=?,inquilino_id=?,tipo=?,concepto=?,importe=?,periodicidad=?,fecha_inicio=?,fecha_fin=?,pagado_por=? WHERE id=?')->execute([$unitId?:null,$tenantId?:null,$type,$concept,$amount,$period,$start,$end,$payer,$id]);
    if($priceChanged){$pdo->prepare("UPDATE cargos SET importe=?,pagado_por=? WHERE recurrente_id=? AND periodo_recurrente>=? AND estado_pago='PENDIENTE'")->execute([$amount,$payer,$id,$priceEffect]);}
    $pdo->commit();
   }else{
    $pdo->prepare('INSERT INTO cargos_recurrentes(unidad_id,inquilino_id,tipo,concepto,importe,periodicidad,fecha_inicio,fecha_fin,pagado_por,activo) VALUES(?,?,?,?,?,?,?,?,?,1)')->execute([$unitId?:null,$tenantId?:null,$type,$concept,$amount,$period,$start,$end,$payer]);$id=(int)$pdo->lastInsertId();$effectDate=substr($start,0,7).'-01';$pdo->prepare('INSERT INTO cargos_recurrentes_precios(recurrente_id,fecha_efecto,importe) VALUES(?,?,?)')->execute([$id,$effectDate,$amount]);
   }
   $created=sync_recurring_charges($pdo);$ok='Plantilla guardada. '.($created?'Se han generado '.$created.' cargos nuevos.':'No había cargos pendientes que generar.');if($id&&isset($priceChanged)&&$priceChanged)$ok.=' El nuevo precio se aplica desde '.$priceEffect.' a los cargos pendientes; los ya pagados se han conservado.';
  }elseif($action==='toggle'){
   $id=(int)($_POST['id']??0);$pdo->prepare('UPDATE cargos_recurrentes SET activo=IF(activo=1,0,1) WHERE id=?')->execute([$id]);$created=sync_recurring_charges($pdo);$ok='Estado de la plantilla actualizado. '.($created?'Se han generado '.$created.' cargos nuevos.':'Los cargos ya registrados se han conservado.');
  }
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'No se pudo guardar la plantilla. Comprueba los datos.':$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM cargos_recurrentes WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}
$units=$pdo->query("SELECT u.id,u.nombre,l.nombre ubicacion_nombre FROM unidades u JOIN ubicaciones l ON l.id=u.ubicacion_id ORDER BY l.nombre,u.nombre")->fetchAll();
$tenants=$pdo->query("SELECT t.id,t.nombre,t.unidad_id,u.nombre unidad_nombre,l.nombre ubicacion_nombre FROM inquilinos t LEFT JOIN unidades u ON u.id=t.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id ORDER BY t.nombre")->fetchAll();
$templates=$pdo->query("SELECT r.*,u.nombre unidad_nombre,l.nombre ubicacion_nombre,t.nombre inquilino_nombre,tu.nombre tenant_unit FROM cargos_recurrentes r LEFT JOIN unidades u ON u.id=r.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id LEFT JOIN inquilinos t ON t.id=r.inquilino_id LEFT JOIN unidades tu ON tu.id=t.unidad_id ORDER BY r.activo DESC,COALESCE(l.nombre,t.nombre),r.concepto")->fetchAll();
function rv(array $row,string $key,$default=''):string{return e($row[$key]??$default);}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(app_setting('titulo_web','APP Alquileres · Gestión de propiedades'))?> · Cargos recurrentes</title><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="stylesheet" href="assets/app.css"><style>:root{--blue:<?=e(app_setting('color_principal','#2859a6'))?>}.recurring-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.recurring-grid .full{grid-column:1/-1}.recurring-help{background:#f3f7fd;border:1px solid #d9e5f5;padding:12px;border-radius:10px;margin-bottom:14px}.status-on{color:#147341;font-weight:700}.status-off{color:#777;font-weight:700}@media(max-width:700px){.recurring-grid{grid-template-columns:1fr}.recurring-grid .full{grid-column:auto}}</style></head><body>
<header class="topbar"><a class="brand" href="index.php"><img src="assets/logo.svg" alt="APP Alquileres" style="width:230px;max-width:30vw;height:auto"></a><div class="userbox"><span><?=e($user['nombre'])?> · <?=e($user['rol'])?></span><a class="btn outline" href="logout.php">Cerrar sesión</a></div></header>
<div class="layout"><nav class="sidebar" aria-label="Menú principal"><button class="mobile-menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav-links" onclick="const n=this.parentElement;const o=n.classList.toggle('mobile-menu-open');this.setAttribute('aria-expanded',String(o));this.querySelector('.toggle-label').textContent=o?'Cerrar menú':'Menú principal';this.querySelector('.toggle-icon').textContent=o?'✕':'☰'"><span class="toggle-label">Menú principal</span><span class="toggle-icon" aria-hidden="true">☰</span></button><div class="mobile-nav-links" id="mobile-nav-links"><div class="nav-heading">MENÚ PRINCIPAL</div><a class="nav-item" href="index.php"><span class="nav-icon">🏠</span><span>Dashboard</span></a><div class="nav-divider"><span>ALQUILERES</span></div><a class="nav-item" href="ubicaciones.php"><span class="nav-icon">🏢</span><span>Ubicaciones e inmuebles</span></a><a class="nav-item" href="index.php?page=inquilinos"><span class="nav-icon">👥</span><span>Inquilinos</span></a><a class="nav-item active" href="recurrentes.php" aria-current="page"><span class="nav-icon">🔁</span><span>Cargos recurrentes</span></a><div class="nav-divider"><span>ECONOMÍA</span></div><a class="nav-item" href="index.php?page=cargos"><span class="nav-icon">📋</span><span>Cargos</span></a><a class="nav-item" href="index.php?page=ingresos"><span class="nav-icon">💶</span><span>Ingresos</span></a><a class="nav-item" href="index.php?page=fianzas"><span class="nav-icon">🔐</span><span>Fianzas</span></a><div class="nav-divider"><span>HERRAMIENTAS</span></div><a class="nav-item" href="estadisticas.php"><span class="nav-icon">📊</span><span>Estadísticas</span></a><?php if($user['rol']==='ADMIN'):?><a class="nav-item" href="index.php?page=usuarios"><span class="nav-icon">⚙️</span><span>Usuarios</span></a><a class="nav-item" href="backup.php"><span class="nav-icon">💾</span><span>Copias de seguridad</span></a><a class="nav-item" href="configuracion.php"><span class="nav-icon">🛠️</span><span>Configuración</span></a><?php endif;?><a class="nav-item" href="ayuda.php"><span class="nav-icon">❔</span><span>Ayuda y manual</span></a></div></nav>
<main class="content"><div class="page-head"><div><h1>Cargos recurrentes</h1><p class="muted">Define cargos que se repiten y se generan automáticamente sin duplicar los ya registrados.</p></div><a class="btn outline" href="index.php?page=cargos">Ver cargos</a></div>
<div class="recurring-help"><strong>Cómo se aplican las plantillas</strong><ul><li>Una plantilla de unidad se aplica a los inquilinos que ocupen esa unidad.</li><li>Una plantilla específica de inquilino sustituye la de unidad cuando coincide el tipo y el concepto.</li><li>La fecha «Desde» de cada plantilla es independiente de la entrada del inquilino: el servicio solo genera cargos desde su propia fecha de inicio, respetando también la entrada y salida del inquilino.</li><li>Si el servicio empieza en cualquier día de un mes, se cobra el mes de inicio completo. La periodicidad trimestral o anual se calcula tomando como referencia el mes de inicio de la plantilla.</li><li>Se generan cargos hasta el mes actual, sin superar la fecha de salida ni la fecha final de la plantilla.</li><li>Los cargos ya registrados nunca se modifican ni se borran automáticamente.</li></ul></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($ok):?><div class="alert success"><?=e($ok)?></div><?php endif;?>
<section class="panel"><div class="page-head"><h2><?=$edit?'Editar plantilla':'Nueva plantilla recurrente'?></h2><?php if($edit):?><a class="btn outline" href="recurrentes.php">Cancelar</a><?php endif;?></div>
<form method="post" class="recurring-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=rv($edit??[],'id','0')?>">
<div><label>Aplicar a *</label><select name="scope" id="scope" required><option value="unidad" <?=empty($edit['inquilino_id'])?'selected':''?>>Ubicación / unidad (base)</option><option value="inquilino" <?=!empty($edit['inquilino_id'])?'selected':''?>>Inquilino (personalizada)</option></select></div>
<div><label>Tipo de cargo *</label><select name="tipo" required><?php foreach($types as $type):?><option value="<?=e($type)?>" <?=rv($edit??[],'tipo','Alquiler')===$type?'selected':''?>><?=e($type)?></option><?php endforeach;?></select></div>
<div id="unit-field"><label>Unidad *</label><select name="unidad_id" id="unidad_id"><?php foreach($units as $u):?><option value="<?=$u['id']?>" <?=((int)($edit['unidad_id']??0)===(int)$u['id'])?'selected':''?>><?=e($u['ubicacion_nombre'].' · '.$u['nombre'])?></option><?php endforeach;?></select></div>
<div id="tenant-field"><label>Inquilino *</label><select name="inquilino_id" id="inquilino_id"><?php foreach($tenants as $t):?><option value="<?=$t['id']?>" <?=((int)($edit['inquilino_id']??0)===(int)$t['id'])?'selected':''?>><?=e($t['nombre'].' · '.($t['ubicacion_nombre']??''). ' / '.($t['unidad_nombre']??'sin unidad'))?></option><?php endforeach;?></select></div>
<div><label>Concepto *</label><input name="concepto" required maxlength="255" value="<?=rv($edit??[],'concepto')?>" placeholder="Ej. Alquiler, Basura, Internet"></div>
<div><label>Importe por periodo (€) *</label><input type="number" name="importe" min="0.01" step="0.01" required value="<?=rv($edit??[],'importe')?>"></div>
<div><label>Periodicidad *</label><select name="periodicidad"><?php foreach($periods as $v=>$label):?><option value="<?=$v?>" <?=rv($edit??[],'periodicidad','MENSUAL')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div>
<div><label>Pagado por *</label><select name="pagado_por"><?php foreach(['Inquilino','Propietario','Otro'] as $v):?><option value="<?=$v?>" <?=rv($edit??[],'pagado_por','Inquilino')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div>
<div><label>Desde *</label><input type="date" name="fecha_inicio" required value="<?=rv($edit??[],'fecha_inicio',date('Y-m-d'))?>"></div>
<div><label>Precio vigente desde (mes) *</label><input type="month" name="fecha_efecto_precio" value="<?=e($edit?substr((string)$edit['fecha_inicio'],0,7):date('Y-m'))?>" required><small>Si cambias el importe, se aplicará desde este mes a los cargos pendientes. Los pagados no se modifican.</small></div>
<div><label>Hasta (opcional)</label><input type="date" name="fecha_fin" value="<?=rv($edit??[],'fecha_fin')?>"></div>
<div class="full actions"><button class="btn primary">Guardar plantilla</button><?php if($edit):?><a class="btn outline" href="recurrentes.php">Cancelar</a><?php endif;?></div></form></section>
<section class="panel"><h2>Plantillas configuradas</h2><div class="table-wrap"><table><thead><tr><th>Ámbito</th><th>Ubicación / inquilino</th><th>Concepto</th><th>Periodicidad</th><th>Importe</th><th>Periodo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($templates as $r):?><tr><td><?=!empty($r['inquilino_id'])?'Inquilino':'Unidad'?></td><td><?=e(!empty($r['inquilino_id'])?($r['inquilino_nombre'].' · '.($r['tenant_unit']??'')):($r['ubicacion_nombre'].' · '.$r['unidad_nombre']))?></td><td><?=e($r['concepto'])?><br><small><?=e($r['tipo'])?></small></td><td><?=e($periods[$r['periodicidad']]??$r['periodicidad'])?></td><td><?=money($r['importe'])?></td><td><?=e($r['fecha_inicio'])?><?=!empty($r['fecha_fin'])?' – '.e($r['fecha_fin']):' – sin fecha final'?></td><td><span class="<?=$r['activo']?'status-on':'status-off'?>"><?=$r['activo']?'Activa':'Inactiva'?></span></td><td class="actions"><a class="btn outline" href="recurrentes.php?edit=<?=$r['id']?>">Editar</a><form method="post" onsubmit="return confirm('¿Cambiar el estado de esta plantilla?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn outline"><?=$r['activo']?'Desactivar':'Activar'?></button></form></td></tr><?php endforeach;?><?php if(!$templates):?><tr><td colspan="8">Todavía no hay plantillas. Puedes empezar creando el alquiler base de una unidad.</td></tr><?php endif;?></tbody></table></div></section>
<footer>APP Alquileres · Cargos recurrentes</footer></main></div>
<script>
const scope=document.getElementById('scope'),unitField=document.getElementById('unit-field'),tenantField=document.getElementById('tenant-field'),unitSelect=document.getElementById('unidad_id'),tenantSelect=document.getElementById('inquilino_id');
function syncScope(){const tenant=scope.value==='inquilino';unitField.hidden=tenant;tenantField.hidden=!tenant;unitSelect.required=!tenant;tenantSelect.required=tenant;}
scope.addEventListener('change',syncScope);syncScope();
</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const nav=document.querySelector('.sidebar');if(!nav)return;const btn=nav.querySelector('.mobile-menu-toggle');const links=nav.querySelector('.mobile-nav-links');if(!btn||!links)return;links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{if(window.matchMedia('(max-width:650px)').matches){nav.classList.remove('mobile-menu-open');btn.setAttribute('aria-expanded','false');btn.querySelector('.toggle-label').textContent='Menú principal';btn.querySelector('.toggle-icon').textContent='☰';}}));});</script></body></html>
